/* =========================================================
   ALCHEMIST BLURB PAGE
   ========================================================= */

.alchemist-blurb-page {
  position: relative;
  width: 100%;
  box-sizing: border-box;
  color: #000000;
  text-align: center;
}



/* =========================================================
   MAIN TITLE
   ========================================================= */

.alchemist-blurb-title {
  font-family: beaufort-pro;
  font-size: 32pt;
  font-weight: 900;
  font-style: italic;
  font-variant-caps: small-caps;
  line-height: 0.9;
  text-align: center;
}

/* =========================================================
   INTRO / STORY TEXT
   ========================================================= */

.alchemist-blurb-copy {
  width: 80%;
  margin:  auto;

  font-family: "EB Garamond", "Garamond", "Palatino Linotype",
               "Book Antiqua", Palatino, serif;

  font-size: 13px;
  font-weight: 900;
  line-height: 1.24;
  letter-spacing: 0.05px;

  text-align: left !important;

  hyphens: auto;
  -webkit-hyphens: auto;
}

/* Longer paragraphs: justified */
.alchemist-blurb-copy .blurb-paragraph {
  display: block;
  width: 100%;
  margin: 0 0 7px 0;

  text-align: justify !important;
  text-align-last: left !important;
}

/* Short standalone lines: always flush left */
.alchemist-blurb-copy .blurb-line {
  display: block;
  width: 100%;
  margin: 0 0 7px 0;

  text-align: left !important;
}

.alchemist-blurb-copy > div:last-child {
  margin-bottom: 0;
}

/* =========================================================
   HORIZONTAL SEPARATORS
   ========================================================= */

.alchemist-blurb-rule {
  width: 100%;
  height: 1px;
  margin: 30px auto 30px auto;
  background: rgb(87, 42, 35);
}

.alchemist-blurb-rule-bottom {
  margin-top: 20px;
  margin-bottom: 40px;
}

/* =========================================================
   THREE CORE FEATURE COLUMNS
   ========================================================= */

.alchemist-blurb-columns {
  width: 100%;
  margin: 0 auto;

  display: flex;
  justify-content: space-between;
  align-items: flex-start;

  gap: 19px;
}

.alchemist-blurb-column {
  flex: 1 1 0;
  min-width: 0;
  width: auto;
  text-align: center;
}

/* =========================================================
   FEATURE ICONS
   ========================================================= */

.alchemist-blurb-icon {
  height: 74px;
  margin: 0 auto 12px auto;

  display: flex;
  align-items: center;
  justify-content: center;
}

.alchemist-blurb-icon img {
  display: block;
  width: 66px;
  height: 66px;
  object-fit: contain;
}

/* =========================================================
   FEATURE TEXT
   ========================================================= */

.alchemist-blurb-feature {
  font-family: "Avenir Condensed";
  font-size: 10pt;
  line-height: 1.12;
  text-align: justify;
  hyphens: auto;
}

.alchemist-blurb-feature strong {
  font-size: 13.5px;
  font-weight: 700;
}

/* Visually normalize the three class icons */
.alchemist-blurb-icon .class-wheel-icon {
  transform: scale(0.88);
}

.alchemist-blurb-icon .class-phoenix-icon {
  transform: scale(1.08);
}

.alchemist-blurb-icon .class-death-icon {
  transform: scale(1.00);
}

/* =========================================================
   BOTTOM CLASS SUMMARY
   ========================================================= */

.alchemist-blurb-summary {
  font-family: "Avenir Condensed";
  width: 72%;
  margin: 0 auto;

  font-size: 10pt;
  line-height: 1.12;
  text-align: center;
}

/* =========================================================
   CLASS COMPLEXITY
   ========================================================= */

.alchemist-complexity {
  display: flex;
  justify-content: center;
  align-items: center;

  gap: 2px;
  margin: 8px auto 0 auto;

  line-height: 0;
}

.alchemist-complexity img {
  display: block;
  width: auto;
  height: 24px;
}


/* =========================================================
   CLASS CENTER ALIGNED
   ========================================================= */

/* Was left aligned before */

.classDetails {
  text-align: center;
}


/* =========================================================
   DICE ICONS - SHARED BASE
   ========================================================= */

/* Basic styling shared by all dice icons */
.die {
display: inline-block;
background-position: center;
background-repeat: no-repeat;
background-size: contain;
}


/* =========================================================
   DICE ICON SIZES
   ========================================================= */
/* Compact die - potion formula tables */
.die-10 {
  width: 10px;
  height: 10px;
  vertical-align: -1px;
}
/* Small inline die - 12px */
.die-12 {
width: 12px;
height: 12px;
vertical-align: -2px;
}

/* Standard inline die - 14px */
.die-14 {
width: 14px;
height: 14px;
vertical-align: -2px;
}

/* Large inline die - 20px */
.die-20 {
width: 20px;
height: 20px;
vertical-align: -4px;
}

/* Extra large die - 28px */
.die-28 {
width: 28px;
height: 28px;
vertical-align: -6px;
}

/* Fill the full width and height of the parent container */
.die-full {
display: block;
width: 100%;
height: 100%;
margin: 0 auto;
vertical-align: 0;
}


/* =========================================================
   D6 CATALYST DICE
   ========================================================= */

/* D6 - Value 1 */
.d6-1 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d6-value-1.svg");
}

/* D6 - Value 2 */
.d6-2 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d6-value-2.svg");
}

/* D6 - Value 3 */
.d6-3 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d6-value-3.svg");
}

/* D6 - Value 4 */
.d6-4 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d6-value-4.svg");
