/* =========================================================
   D6 SPECIAL CATALYST DICE
   ========================================================= */

/* D6 - Any / Question */
.d6-question {
  background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d6-value-question.svg");
}

/* D6 - Variable X */
.d6-x {
