   ========================================================= */

/* D8 - Value 1 */
.d8-1 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-1.svg");
}

/* D8 - Value 2 */
.d8-2 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-2.svg");
}

/* D8 - Value 3 */
.d8-3 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-3.svg");
}

/* D8 - Value 4 */
.d8-4 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-4.svg");
}

/* D8 - Value 5 */
.d8-5 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-5.svg");
}

/* D8 - Value 6 */
.d8-6 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-6.svg");
}

/* D8 - Value 7 */
.d8-7 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-7.svg");
}

/* D8 - Value 8 */
.d8-8 {
background-image: url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/d8-value-8.svg");
}

/* =========================================================
   DICE FORMULAE
   ========================================================= */

/* Keeps dice and formula symbols consistently aligned */
.dice-formula {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 1px;
  white-space: nowrap;
  line-height: 1;
  width: max-content;
  max-width: 100%;
}

/* Prevent dice from growing or shrinking inside formulae */
.dice-formula .die {
  display: inline-block;
  flex-grow: 0;
  flex-shrink: 0;
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
}

/* Fixed 12px dice inside potion formulae */
.dice-formula .die-12 {
  width: 12px !important;
  height: 12px !important;
  min-width: 12px;
  min-height: 12px;
  max-width: 12px;
  max-height: 12px;
  flex-basis: 12px;
  aspect-ratio: 1 / 1;
  vertical-align: 0;
}

/* =========================================================
   ALCHEMIST ART - SHARED SETTINGS
   ========================================================= */

/* Large artwork used on Alchemist subclass spreads */
.essence-art {
display:block;
background-position:center;
background-repeat:no-repeat;
background-size:contain;
margin:0 auto;
}

/* Small icons used in Alchemical Revelation cards */
.revelation-icon {
display:block;
background-position:center;
background-repeat:no-repeat;
background-size:contain;
margin:0 auto;
}


/* =========================================================
   CLASS ART - INTRO
   ========================================================= */

/* Wheel Icon - 225 × 225 px */
.class-wheel {
width:225px;
height:225px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/class-of-chaos.svg");
}


/* =========================================================
   SUBCLASS ART - ESSENCES
   ========================================================= */

/* Essence of Havoc - 225 × 225 px */
.essence-of-havoc {
width:225px;
height:225px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/essence-of-havoc.svg");
}

/* Essence of Renewal - 200 × 200 px */
.essence-of-renewal {
width:200px;
height:200px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/essence-of-renewal.svg");
}

/* Essence of Toxins - 225 × 225 px */
.essence-of-toxins {
width:225px;
height:225px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/essence-of-toxins.svg");
}

/* Essence of Vigor - 350 × 250 px */
.essence-of-vigor {
width:350px;
height:250px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/essence-of-vigor.svg");
}

/* Essence of Creation - 190 × 190 px */
.essence-of-creation {
width:190px;
height:190px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/essence-of-creation.svg");
}

/* Essence of Souls - 225 × 225 px */
.essence-of-souls {
width:225px;
height:225px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/essence-of-souls.svg");
}

/* =========================================================
   COMBAT STIMULANTS LIST
   ========================================================= */

.stimulant-list {
  margin-left: 18px;
}


/* =========================================================
   HOMUNCULUS NOTE
   ========================================================= */

.homunculus-note,
.homunculus-note * {
  font-family: "Avenir Condensed" !important;
  font-size: 9.5px !important;
  line-height: 1.08 !important;
}


/* =========================================================
   HOMUNCULUS TRACKER
   ========================================================= */

.homunculus-sheet {
  width: 100%;
  color: #000000;
}

.homunculus-sheet .sheet-title {
  text-align: center;
  font-family: beaufort-pro;
  font-size: 32px;
  font-weight: 900;
  line-height: 1;
  margin: 0 0 12px 0;
}

.homunculus-sheet table {
  position: relative;
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 15px;
  line-height: 1;
}

.homunculus-sheet th {
  font-family: beaufort-pro;
  padding: 0px -1px 0px 0px;
  text-align: center;
  font-style: italic;
  font-weight: 900;
  font-size: 12.5px;
}

.homunculus-sheet td {
  padding: 6px 6px;
  vertical-align: middle;
}


/* Print-safe alternating row fill.
   Each shaded cell contains a real SVG rectangle instead of
   a CSS background, so the grey rows print even when
   "Background graphics" are disabled. */
.homunculus-sheet td {
  position: relative;
  overflow: hidden;
}

.homunculus-row-fill {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.homunculus-cell-content {
  position: relative;
  z-index: 1;
  display: inline-block;
}

.homunculus-sheet td.effect-col .homunculus-cell-content {
  display: block;
  width: 100%;
}

/* Homebrew Evolution rows use real SVG images as well. */
.homunculus-inline-die {
  display: inline-block;
  width: 14px;
  height: 14px;
  object-fit: contain;
  vertical-align: -3px;
}

.homunculus-write-line {
  display: inline-block;
  width: 86%;
  height: 12px;
  margin-left: 4px;
  border-bottom: 1px solid #575758;
  vertical-align: -1px;
}

/* Alternating row shading is rendered with actual inline SVGs.
   This remains visible when browser "Background graphics" are disabled. */
.homunculus-sheet tbody tr {
  background: transparent !important;
}

/* Four Catalyst slot columns */
.homunculus-sheet .slot-col {
  width: 8%;
  text-align: center;
}

/* Effect column */
.homunculus-sheet .effect-col {
  width: 68%;
  text-align: left;
}

/* Adaptation names */
.homunculus-sheet .effect-col strong {
  font-size: 15px;
  font-weight: 700;
}

/* UNLOCKS AT */
.homunculus-sheet .unlocks-head {
  font-family: beaufort-pro;
  text-align: center;
  font-size: 15px;
  letter-spacing: 0px;
  padding-bottom: 1px;
}

/* Effect column body */
.homunculus-sheet td.effect-col {
  width: 68%;
  text-align: left;
}

/* EFFECT header only */
.homunculus-sheet th.effect-col {
  font-family: beaufort-pro;
  width: 68%;
  text-align: center;
  font-size: 15px;
  font-weight: 900;
}


/* =========================================================
   HOMUNCULUS DIE SLOTS
   ========================================================= */

.slot-box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
}

/* Actual D6 SVG */
.slot-die-img {
  display: block;
  width: 28px;
  height: 28px;
  object-fit: contain;
}

.evolution-die {
  display: inline-block;
  width: 14px;
  height: 14px;
  object-fit: contain;
  vertical-align: -3px;
}


/* =========================================================
   SLOT UNLOCK GRADATION
   The SVG itself is recolored.
   No opacity and no background required.
   ========================================================= */

/* LVL 3 - darkest */
.slot-box.lvl3 .slot-die-img {
  filter: invert(15%);
}

/* LVL 7 */
.slot-box.lvl7 .slot-die-img {
  filter: invert(30%);
}

/* LVL 11 */
.slot-box.lvl11 .slot-die-img {
  filter: invert(45%);
}

/* LVL 15 - lightest */
.slot-box.lvl15 .slot-die-img {
  filter: invert(60%);
}

/* =========================================================
   SMALLER NOTES
   ========================================================= */

.small,
.small * {
  font-family: "Avenir Condensed" !important;
  font-size: 10.0px !important;
  line-height: 1.08 !important;
}



/* =========================================================
   ALCHEMICAL REVELATION ICONS
   ========================================================= */

/* Practiced Throw - 40 × 40 px */
.practiced-throw {
width:40px;
height:40px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/practiced-throw.svg");
}

/* Double Dose - 40 × 40 px */
.double-dose {
width:40px;
height:40px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/double-dose.svg");
}

/* Swift Sip - 36 × 36 px */
.swift-sip {
width:36px;
height:36px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/swift-sip.svg");
}

/* Blood Synthesis - 36 × 36 px */
.blood-synthesis {
width:36px;
height:36px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/blood-synthesis.svg");
}

/* Shaped Charge - 36 × 36 px */
.shaped-charge {
width:36px;
height:36px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/shaped-charge.svg");
}

/* Critical Mass - 45 × 45 px */
.critical-mass {
width:45px;
height:45px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/critical-mass.svg");
}

/* Stable Formula - 45 × 50 px */
.stable-formula {
width:45px;
height:50px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/stable-formula.svg");
}

/* Altered Physique - 36 × 36 px */
.altered-physique {
width:36px;
height:36px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/altered-physique.svg");
}

/* Lessons Learnt - 40 × 40 px */
.lessons-learnt {
width:40px;
height:40px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/lessons-learnt.svg");
}

/* Compound Boon - 48 × 48 px */
.compound-boon {
width:48px;
height:48px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/compound-boon.svg");
}

/* Flash Distillation - 40 × 40 px */
.flash-destillation {
width:40px;
height:40px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/flash-destillation.svg");
}

/* Reactive Reagents - 40 × 40 px */
.reactive-reagents {
width:40px;
height:40px;
background-image:url("https://raw.githubusercontent.com/PerikleZ/NimbrewART/main/reactive-reagents.svg");
}

/* =========================================================
   PDF VECTOR LAYERS
   The crisp Revelation cards use positioned child layers
   inside {{wide}}. Apply the same pattern to the other
   wide content so Chrome keeps text/SVGs as separate paint
   layers during PDF export.
   ========================================================= */

/* Direct content inside a wide block */
.wide > div,
.wide > table {
  position: relative;
}

/* Tables should always be their own positioned paint layer */
.wide table,
.pdf-vector {
  position: relative;
}

/* Subclass SVG artwork should also be painted separately */
.essence-art {
  position: relative;
}

/* =========================================================
   VECTOR-SAFE SECTION BANNERS
   Keep clip-path on the background only, not on the text.
   ========================================================= */

.vector-banner {
  font-family: beaufort-pro;
  position: relative;
  margin: 0 auto 14px auto;
  padding: 5px 18px;
  text-align: center;
  color: #ffffff;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.vector-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(136, 97, 99, 0.75);
  clip-path: polygon(10% 0,90% 0,100% 50%,90% 100%,10% 100%,0 50%);
}

.vector-banner > span {
  position: relative;
  display: block;
}

.vector-banner-170 {
  width: 140px;
}

.vector-banner-180 {
  width: 180px;
}

.vector-banner-250 {
  width: 250px;
}

.vector-class {
  font-family: beaufort-pro;
  position: relative;
  margin: 0 auto 14px auto;
  padding: 5px 18px;
  text-align: center;
  color: #ffffff;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.vector-class::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(136, 97, 99, 0.75);
  clip-path: polygon(10% 0,90% 0,100% 50%,90% 100%,10% 100%,0 50%);
}

.vector-class > span {
  position: relative;
  display: block;
}

.vector-class-140 {
  width: 140px;
}

.vector-class-270 {
  width: 270px;
}

/* =========================================================
   PRINT-SAFE VECTOR BANNER
   Shape AND text live inside the same inline SVG, so there
   is no stacking-order problem and no reliance on CSS
   background printing.
   ========================================================= */

.print-vector-banner {
  font-family: beaufort-pro;
  position: relative;
  box-sizing: border-box;
  height: 26px;
  margin: 0 auto 14px auto;

  display: flex;
  align-items: center;
  justify-content: center;

  text-align: center;
  color: #ffffff;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.print-vector-banner-svg {
  position: absolute;
  inset: 0;
  z-index: 0;

  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.print-vector-banner > span {
  position: relative;
  z-index: 1;

  display: block;
  color: inherit;
  font: inherit;
  line-height: 1;
}

.print-vector-banner-250 {
  width: 250px;
}


/* =========================================================
   POTION FORMULAE SHEET
   ========================================================= */

.potion-sheet {
  position: relative;
  width: 96%;
  margin: 10px auto 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: 136px;
  gap: 9px 10px;
  box-sizing: border-box;
}

/* =========================================================
   POTION CARD
   Fixed dimensions keep every card identical, regardless
   of effect length or the number of formula dice.
   ========================================================= */

.potion-card {
  font-family: "Avenir Condensed";
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 136px;
  min-height: 136px;
  max-height: 136px;
  padding: 5px 8px 5px 8px;
  border: 1.3px solid #575758;
  border-radius: 9px;
  display: flex;
  flex-direction: column;
  text-align: center;
  color: #000000;
  overflow: hidden;
  break-inside: avoid;
}

/* =========================================================
   POTION NAME
   ========================================================= */

.potion-name {
  font-family: beaufort-pro;
  flex: 0 0 15px;
  height: 15px;
  margin: 0 1px 3px 1px;
  font-size: 12.2px;
  font-weight: 900;
  line-height: 1.05;
  text-align: center;
  white-space: nowrap;
}

/* =========================================================
   POTION EFFECT
   Long effects receive smaller type through modifier classes.
   ========================================================= */

.potion-effect {
  flex: 1 1 auto;
  min-height: 0;
  padding: 0 2px;
  font-size: 10.1px;
  line-height: 1.12;
  text-align: center;
  overflow: hidden;
  hyphens: auto;
  -webkit-hyphens: auto;
}

.potion-effect.potion-effect-small {
  font-size: 9.4px;
  line-height: 1.1;
}

.potion-effect.potion-effect-xsmall {
  font-size: 8.8px;
  line-height: 1.08;
}

/* =========================================================
   POTION FORMULA DICE
   The whole formula area has a fixed height so larger
   recipes never increase the card or grid row height.
   Dice are intentionally larger for quick table readability.
   ========================================================= */

.potion-dice {
  flex: 0 0 44px;
  height: 44px;
  min-height: 44px;
  max-height: 44px;
  margin: 1px 0 1px 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 1px;
  line-height: 1;
  overflow: hidden;
}

.potion-dice-row {
  height: 21px;
  min-height: 21px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 2px;
  white-space: nowrap;
  line-height: 1;
}

.potion-dice img {
  display: block;
  width: 20px;
  height: 20px;
  min-width: 20px;
  min-height: 20px;
  max-width: 20px;
  max-height: 20px;
  object-fit: contain;
  flex: 0 0 20px;
}

.potion-symbol {
  display: inline-block;
  flex: 0 0 auto;
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1;
  color: #000000;
}

.potion-or {
  display: inline-block;
  flex: 0 0 auto;
  margin-right: 1px;
  font-size: 8.8px;
  font-weight: 700;
  line-height: 1;
  color: #777372;
}

/* D8 formula dice need a little more visual weight than the D6 icons. */
.potion-souls .potion-dice img {
  width: 28px;
  height: 28px;
  min-width: 28px;
  min-height: 28px;
  max-width: 28px;
  max-height: 28px;
  flex-basis: 28px;
}

/* Antidote: center both alternatives on the same vertical axis.
   OR sits between the rows without taking up horizontal space. */
.potion-antidote {
  position: relative;
}

.potion-antidote .potion-dice-row {
  width: 100%;
  justify-content: center;
}

.potion-antidote .potion-or-between {
  position: absolute;
  left: 7px;
  top: 50%;
  margin: 0;
  transform: translateY(-50%);
}

/* =========================================================
   POTION META FOOTER
   Tier and source now share the bottom line.
   ========================================================= */

.potion-meta {
  flex: 0 0 12px;
  height: 12px;
  min-height: 12px;
  margin-top: 1px;
  padding: 3px 2px 0 2px;
  border-top: 1px solid rgba(87, 87, 88, 0.23);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 5px;
  color: #85817e;
  line-height: 1;
}

.potion-meta-tier {
  flex: 0 0 auto;
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.2px;
  white-space: nowrap;
}

.potion-meta-source {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 6.3px;
  font-weight: 700;
  letter-spacing: 0.18px;
  text-align: right;
  white-space: nowrap;
}

/* =========================================================
   POTION SHEET NOTE
   ========================================================= */

.potion-sheet-note {
  width: 92%;
  margin: 8px auto 0 auto;
  font-size: 7.4px;
  font-style: italic;
  line-height: 1.1;
  text-align: center;
  color: #777372;
}


/* =========================================================
   HOMEBREW POTION ROWS
   ========================================================= */

/* Separator between published formulae and blank homebrew cards. */
.potion-homebrew-divider {
  position: relative;
  width: 96%;
  height: 1px;
  margin: 8px auto 6px auto;
  background: rgb(87, 42, 35);
}

/* One additional fixed row per potion page. */
.potion-homebrew-sheet {
  margin-top: 0;
  grid-auto-rows: 136px;
}

/* Keep the blank cards exactly the same size as all other potion cards. */
.potion-homebrew {
  height: 136px;
  min-height: 136px;
  max-height: 136px;
}

/* Potion of ______ : leave a long writing line for a handwritten name. */
.potion-homebrew-name {
  display: flex;
  align-items: baseline;
  justify-content: flex-start;
  gap: 4px;
  padding: 0 3px;
  text-align: left;
  white-space: nowrap;
}

.potion-homebrew-name > span:first-child {
  flex: 0 0 auto;
}

.potion-homebrew-name-line {
  display: inline-block;
  flex: 1 1 auto;
  min-width: 0;
  height: 10px;
  border-bottom: 1px solid rgba(87, 87, 88, 0.65);
}

/* Empty writing area for the custom effect and Catalyst formula. */
.potion-homebrew-space {
  flex: 1 1 auto;
  min-height: 0;
}


/* =========================================================
   HOMUNCULUS TRACKER - PRINT SAFETY
   ========================================================= */

@media print {
  .print-vector-banner-svg,
  .homunculus-row-fill,
  .slot-die-img,
  .evolution-die,
  .homunculus-inline-die {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .homunculus-sheet tbody tr {
    background: transparent !important;
  }
}


/* =========================================================
   CATALYST DICE QUICK REFERENCE
   Print-safe table: dice are real SVG images and shaded
   rows use inline SVG rectangles rather than CSS backgrounds.
   ========================================================= */

.print-vector-banner-220 {
  width: 220px;
}

.catalyst-reference-sheet {
  font-family: "Avenir Condensed";
  position: relative;
  width: 100%;
  color: #000000;
}

.catalyst-reference-sheet table {
  position: relative;
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 10.2px;
  line-height: 1.1;
  color: #000000;
}

.catalyst-reference-sheet th {
  font-family: beaufort-pro;
  padding: 2px 6px 5px 6px;
  font-size: 12.5px;
  font-weight: 900;
  font-style: italic;
  line-height: 1;
  text-align: center;
  vertical-align: bottom;
}

.catalyst-reference-sheet td {
  position: relative;
  padding: 4px 7px;
  vertical-align: middle;
  overflow: hidden;
}

.catalyst-reference-sheet tr {
  background: transparent !important;
}

.catalyst-reference-sheet .catalyst-die-col {
  width: 16%;
  text-align: center;
}

.catalyst-reference-sheet .catalyst-use-col {
  width: 84%;
  text-align: left;
}

.catalyst-row-fill {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.catalyst-cell-content {
  position: relative;
  z-index: 1;
}

.catalyst-use-list {
  display: block;
  width: 100%;
}

.catalyst-use {
  display: block;
  margin: 0 0 2px 0;
}

.catalyst-use:last-child {
  margin-bottom: 0;
}

.catalyst-use strong {
  font-weight: 700;
}

.catalyst-die-pair {
  min-height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  line-height: 0;
}

.catalyst-ref-die {
  display: block;
  width: 29px;
  height: 29px;
  object-fit: contain;
  flex: 0 0 29px;
}

.catalyst-ref-d8 {
  width: 31px;
  height: 31px;
  flex-basis: 31px;
}

.catalyst-ref-d8-only {
  width: 35px;
  height: 35px;
  flex-basis: 35px;
}

.catalyst-ref-any {
  width: 32px;
  height: 32px;
  flex-basis: 32px;
}

.catalyst-die-matching {
  gap: 2px;
}

.catalyst-die-matching .catalyst-ref-die {
  width: 28px;
  height: 28px;
  flex-basis: 28px;
}

/* =========================================================
   CATALYST REFERENCE - PRINT SAFETY
   ========================================================= */

@media print {
  .catalyst-row-fill,
  .catalyst-ref-die {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .catalyst-reference-sheet tr {
    background: transparent !important;
  }
}


